/* Liner notes for the Record Shelf: a few lines from Wikipedia about each album (or its singer or band),
   shown under the player. Text from Wikipedia (CC BY-SA), each with a link back to its article.
   To change one, edit its text; to drop one, delete its line. */
window.RECORD_NOTES = {
  "https://archive.org/details/ella-fitzgerald-louis-armstrong-porgy-bess-vinyl-rip": {"kind": "artist", "name": "Ella Fitzgerald", "text": "Ella Jane Fitzgerald was an American jazz vocalist, songwriter and composer, sometimes referred to as the \"First Lady of Song\", \"Queen of Jazz\", and \"Lady Ella\". She was noted for her purity of tone, impeccable diction, phrasing, timing, intonation, and a \"horn-like\" improvisational ability, particularly in her scat singing.", "url": "https://en.wikipedia.org/wiki/Ella_Fitzgerald"},
  "https://archive.org/details/lp_frank-sinatra-conducts-the-music-of-ale_frank-sinatra-the-alec-wilder-octet-ale": {"kind": "album", "name": "Frank Sinatra Conducts the Music of Alec Wilder", "text": "Frank Sinatra Conducts the Music of Alec Wilder is an album of compositions by Alec Wilder, conducted by Frank Sinatra, released in 1946. This was Sinatra's recording debut as a conductor. He later conducted a full symphony orchestra on Frank Sinatra Conducts Tone Poems of Color (1956), including two further Wilder compositions.", "url": "https://en.wikipedia.org/wiki/Frank_Sinatra_Conducts_the_Music_of_Alec_Wilder"},
  "https://archive.org/details/lp_at-the-sands_nat-king-cole": {"kind": "artist", "name": "Nat King Cole", "text": "Nathaniel Adams Coles, known professionally as Nat King Cole, was an American singer, jazz pianist, and actor. Cole's career as a jazz and pop vocalist started in the late 1930s and spanned almost three decades, during which he found success and recorded over 100 songs that became hits on the pop charts.", "url": "https://en.wikipedia.org/wiki/Nat_King_Cole"},
  "https://archive.org/details/danny_kaye_louis_armstrong-the_five_pennies-vinyl-1959": {"kind": "artist", "name": "Danny Kaye", "text": "Danny Kaye was an American actor, dancer, singer and comedian. His performances featured physical comedy, idiosyncratic pantomimes, and rapid-fire novelty songs.", "url": "https://en.wikipedia.org/wiki/Danny_Kaye"},
  "https://archive.org/details/basie-count-1962-and-the-kansas-city": {"kind": "album", "name": "Count Basie and the Kansas City 7", "text": "Count Basie and the Kansas City 7 is an album by American jazz bandleader and pianist Count Basie featuring small group performances recorded in 1962 for the Impulse! label.", "url": "https://en.wikipedia.org/wiki/Count_Basie_and_the_Kansas_City_7"},
  "https://archive.org/details/lp_25-great-country-artists-singing-their_various-cowboy-copas-eddie-dean-fiddlin": {"kind": "artist", "name": "Patsy Cline", "text": "Patsy Cline was an American singer. One of the most influential vocalists of the 20th century, she was known as one of the first country music artists to successfully cross over into pop music. Cline had several major hits during her eight-year recording career, including two number-one hits on the Billboard Hot Country and Western Sides chart.", "url": "https://en.wikipedia.org/wiki/Patsy_Cline"},
  "https://archive.org/details/1958_elvis_golden_records_mono_cd": {"kind": "album", "name": "Elvis' Golden Records", "text": "Elvis' Golden Records is a compilation album by American rock and roll singer Elvis Presley, issued by RCA Victor in March 1958. It compiled his hit singles released in 1956 and 1957, and is widely believed to be the first greatest hits album in rock and roll history. It is the first of five RCA Victor Elvis' Golden/Gold Records compilations, the first four of which were issued during Presley's lifetime.", "url": "https://en.wikipedia.org/wiki/Elvis'_Golden_Records"},
  "https://archive.org/details/thats-blues-rock-lp-2-mercury-141101": {"kind": "artist", "name": "Chuck Berry", "text": "Charles Edward Anderson Berry was an American guitarist, singer, and songwriter who was one of the pioneers of rock and roll. Nicknamed the \"Father of Rock and Roll\", he refined and developed rhythm and blues into the major elements that made rock and roll distinctive with songs such as \"Maybellene\" (1955), \"Roll Over Beethoven\" (1956), \"Rock and Roll Music\" (1957), and \"Johnny B. Goode\" (1958).", "url": "https://en.wikipedia.org/wiki/Chuck_Berry"},
  "https://archive.org/details/buddy-holly-coral-epc-94123": {"kind": "artist", "name": "Buddy Holly", "text": "Charles Hardin Holley, known professionally by his stage name Buddy Holly, was an American singer, songwriter, lead guitarist and co-founder of the Crickets, who was a central and pioneering figure of rock and roll. He was born to a musical family in Lubbock, Texas, during the Great Depression, and learned to play guitar and sing alongside his two siblings.", "url": "https://en.wikipedia.org/wiki/Buddy_Holly"},
  "https://archive.org/details/lp_deep-night_the-ray-charles-singers_0": {"kind": "artist", "name": "Ray Charles", "text": "Ray Charles was an American musician, singer, songwriter, vocal arranger and conductor who was best known as organizer and leader of the Ray Charles Singers, who accompanied Perry Como on his records and television shows for 35 years and were also known for a series of 30 choral record albums produced in the 1950s and 1960s for the MGM, Essex, Decca and Command labels.", "url": "https://en.wikipedia.org/wiki/Ray_Charles_(conductor)"},
  "https://archive.org/details/lp_a-taste-of-tequila_the-mariachi-brass-chet-baker": {"kind": "album", "name": "A Taste of Tequila", "text": "A Taste of Tequila is an album by jazz trumpeter Chet Baker and the Mariachi Brass recorded in 1965 and released on the World Pacific label.", "url": "https://en.wikipedia.org/wiki/A_Taste_of_Tequila"},
  "https://archive.org/details/03-miles-davis-john-coltrane-konserthuset-stockholm-march-22-1960": {"kind": "artist", "name": "Miles Davis", "text": "Miles Dewey Davis III was an American trumpeter, bandleader, composer, and painter. He is among the most influential and acclaimed figures in the history of jazz and 20th-century music. In a career spanning nearly five decades, Davis was at the forefront of several major stylistic developments in jazz, including bebop, cool jazz, hard bop, third stream, modal jazz, avant-garde jazz and jazz fusion.", "url": "https://en.wikipedia.org/wiki/Miles_Davis"},
  "https://archive.org/details/lp_pop-hit-party_various-doris-day-frank-de-vol-and-his": {"kind": "artist", "name": "Doris Day", "text": "Doris Day was an American actress and singer. With an entertainment career that spanned 75 years, Day was one of the most popular and acclaimed female singers of the 1940s and 1950s, with a parallel career as a leading actress in Hollywood films, where she became one of the biggest box-office stars of the 1960s. She was known for her on-screen girl next door image and her distinctive singing voice.", "url": "https://en.wikipedia.org/wiki/Doris_Day"},
  "https://archive.org/details/lp_the-versatile-brenda-lee_brenda-lee": {"kind": "album", "name": "The Versatile Brenda Lee", "text": "The Versatile Brenda Lee is the thirteenth studio album by American singer Brenda Lee. It was released on May 17, 1965, by Decca Records and was her twelfth studio album. The album was a collection of 12 tracks and was named for the album's mixed range of material. Of its songs was Lee's single \"Truly, Truly True\", which became a charting US single in 1965. The album was met with mixed reviews following its release.", "url": "https://en.wikipedia.org/wiki/The_Versatile_Brenda_Lee"},
  "https://archive.org/details/lp_live-from-the-brooklyn-fox-in-his-record-b_various-ben-e-king-gene-pitney-jan-and-dea": {"kind": "artist", "name": "The Ronettes", "text": "The Ronettes were an American girl group from Washington Heights, Manhattan, New York City. The group consisted of the lead singer Veronica Bennett, her older sister Estelle Bennett, and their cousin Nedra Talley. They had sung together since they were teenagers, then known as \"The Darling Sisters\".", "url": "https://en.wikipedia.org/wiki/The_Ronettes"},
  "https://archive.org/details/baby-its-cold-outside-vocals-instrumental": {"kind": "album", "name": "A Winter Romance", "text": "A Winter Romance is the fifth studio album by Dean Martin, accompanied by an orchestra arranged and conducted by Gus Levene. While not exclusively a Christmas album, it features several songs associated with Christmas as part of its larger winter theme. It was Martin's only Christmas themed album for Capitol Records. Martin later recorded The Dean Martin Christmas Album for Reprise Records in 1966.", "url": "https://en.wikipedia.org/wiki/A_Winter_Romance"},
  "https://archive.org/details/lp_deep-in-my-heart_jose-ferrer-merle-oberon-helen-traubel": {"kind": "artist", "name": "Rosemary Clooney", "text": "Rosemary Clooney was an American pop and jazz singer and actress. She came to prominence with the song \"Come On-a My House\" (1951), which was followed by \"Tenderly\" (1951), \"Half as Much\" (1952), \"Botch-a-Me\" (1952), \"Mambo Italiano\" (1954), \"Hey There\" (1954), \"This Ole House\" (1954), and \"Sway\" (1960), a remake of \"¿Quién será?\".", "url": "https://en.wikipedia.org/wiki/Rosemary_Clooney"},
  "https://archive.org/details/lp_the-golden-age-of-the-dance-bands_the-poll-winners-of-1940-glenn-miller-tomm": {"kind": "artist", "name": "Glenn Miller", "text": "Alton Glen \"Glenn\" Miller was an American big band conductor, arranger, composer, trombonist, and recording artist before and during World War II, when he was an officer in the US Army Air Forces. His civilian band, Glenn Miller and his Orchestra, was one of the most popular and successful bands of the 20th century and the big-band era.", "url": "https://en.wikipedia.org/wiki/Glenn_Miller"},
  "https://archive.org/details/les-and-mary-capitol-w-577-side-a": {"kind": "album", "name": "Les and Mary", "text": "Les and Mary  is a studio album released by Les Paul and Mary Ford in 1955 on Capitol Records. The album was available in multiple formats, including a single 12-inch LP (W-577), as a 10-inch double-album (H-1-2-577), and with two separate options as a 45 rpm EP set, one with 2 tracks per side, the other with four tracks per side. Additionally, the album was released in true album format as 78 rpm.", "url": "https://en.wikipedia.org/wiki/Les_and_Mary"},
  "https://archive.org/details/with-his-hot-and-blue-guitar": {"kind": "album", "name": "Johnny Cash with His Hot and Blue Guitar!", "text": "Johnny Cash with His Hot and Blue Guitar! is the debut studio album by American singer Johnny Cash, released on October 11, 1957. It includes four of his hit singles, among them \"I Walk the Line\".", "url": "https://en.wikipedia.org/wiki/Johnny_Cash_with_His_Hot_and_Blue_Guitar!"},
  "https://archive.org/details/02-hank-williams-mgm-ep-608-side-a-message-to-my-mother": {"kind": "artist", "name": "Hank Williams", "text": "Hiram \"Hank\" Williams was an American singer, songwriter, and musician. An early pioneer of country music, he is regarded as one of the most significant and influential musicians of the 20th century. Williams recorded 55 singles that reached the top 10 of the Billboard Country & Western Best Sellers chart, 5 of which were released posthumously, and 12 of which reached No. 1.", "url": "https://en.wikipedia.org/wiki/Hank_Williams"},
  "https://archive.org/details/lp_sarah-vaughan-and-dizzie-gillespie-and_various-floorshow-culley-orchestra-lock": {"kind": "artist", "name": "Sarah Vaughan", "text": "Sarah Lois Vaughan was an American jazz singer and pianist. Nicknamed \"Sassy\", \"The Divine One\", and the \"Queen of Bebop\", music critic Scott Yanow wrote that she had \"one of the most wondrous voices of the 20th century\". Her accolades include the 1989 NEA Jazz Masters honor, and a Grammy Award from a total of nine nominations. Vaughan is also the recipient of the Grammy Lifetime Achievement Award.", "url": "https://en.wikipedia.org/wiki/Sarah_Vaughan"},
  "https://archive.org/details/lp_aint-that-good-news_sam-cooke_item": {"kind": "album", "name": "Ain't That Good News", "text": "Ain't That Good News is the eleventh and final studio album by the American R&B and soul singer-songwriter Sam Cooke. It was released in February 1964 through RCA Victor Records. Recording sessions for the album took place at RCA Victor's Music Center of the World Studio in February and December 1963 and January 1964. The cover photo was taken by American photographer Wallace Seawell.", "url": "https://en.wikipedia.org/wiki/Ain't_That_Good_News"},
  "https://archive.org/details/lp_the-exciting-connie-francis_connie-francis": {"kind": "album", "name": "The Exciting Connie Francis", "text": "The Exciting Connie Francis is a studio album recorded by American pop singer Connie Francis. It is the second album Francis cut for MGM Records.", "url": "https://en.wikipedia.org/wiki/The_Exciting_Connie_Francis"},
  "https://archive.org/details/Thelonious-Monk-Tivoli-Copenhagen-Denmark-2-21-1964": {"kind": "artist", "name": "Thelonious Monk", "text": "Thelonious Sphere Monk was an American jazz pianist and composer. He had a unique improvisational style and made numerous contributions to the standard jazz repertoire, including \"'Round Midnight\", \"Blue Monk\", \"Straight, No Chaser\", \"Ruby, My Dear\", \"In Walked Bud\", and \"Well, You Needn't\". As of 2009, Monk was the second-most-recorded jazz composer in history, after Duke Ellington.", "url": "https://en.wikipedia.org/wiki/Thelonious_Monk"},
  "https://archive.org/details/lp_the-soul-of-jazz-percussion_various-albert-heath-art-blakey-arthur-tay": {"kind": "artist", "name": "Art Blakey", "text": "Arthur Blakey was an American jazz drummer and bandleader.", "url": "https://en.wikipedia.org/wiki/Art_Blakey"},
  "https://archive.org/details/lp_alabama-concerto_john-benson-brooks-cannonball-adderley": {"kind": "album", "name": "Alabama Concerto", "text": "Alabama Concerto is an album by composer John Benson Brooks featuring saxophonist Cannonball Adderley and trumpeter Art Farmer; it was released on the Riverside label in 1958.", "url": "https://en.wikipedia.org/wiki/Alabama_Concerto"},
  "https://archive.org/details/lp_stan-getz-volume-one_stan-getz-quartet-stan-getz-tenor-sax-s": {"kind": "artist", "name": "Stan Getz", "text": "Stan Getz was an American jazz saxophonist. Playing primarily the tenor saxophone, Getz was known as \"The Sound\" because of his warm, lyrical tone, with his prime influence being the wispy, mellow timbre of his idol, Lester Young. Coming to prominence in the late 1940s with Woody Herman's big band, Getz is described by critic Scott Yanow as \"one of the all-time great tenor saxophonists\".", "url": "https://en.wikipedia.org/wiki/Stan_Getz"},
  "https://archive.org/details/lp_encore-more-of-the-concert-sound-of-henry_henry-mancini": {"kind": "artist", "name": "Henry Mancini", "text": "Henry Mancini was an American composer, conductor, arranger, pianist and flutist, best known as a composer of film and television scores. Often cited as one of the greatest composers in the history of film, he won four Academy Awards, a Golden Globe, and twenty Grammy Awards, plus a posthumous Grammy Lifetime Achievement Award in 1995.", "url": "https://en.wikipedia.org/wiki/Henry_Mancini"},
  "https://archive.org/details/lp_perfume-set-to-music_harry-revel-les-baxter-dr-samuel-j-hoffman": {"kind": "artist", "name": "Les Baxter", "text": "Leslie Thompson Baxter was an American composer, conductor, and musician. After working as an arranger and composer for swing bands, he developed his own style of easy listening music, known as exotica, and scored over 250 radio, television and motion pictures numbers.", "url": "https://en.wikipedia.org/wiki/Les_Baxter"},
  "https://archive.org/details/lp_anita-o-day-at-mister-kellys_anita-oday": {"kind": "album", "name": "Anita O'Day at Mister Kelly's", "text": "Anita O'Day at Mister Kelly's is a 1958 live album by Anita O'Day, recorded at Mister Kelly's in Chicago.", "url": "https://en.wikipedia.org/wiki/Anita_O'Day_at_Mister_Kelly's"},
  "https://archive.org/details/lp_road-show_stan-kenton-and-his-orchestra-june-christy": {"kind": "artist", "name": "Stan Kenton", "text": "Stanley Newcomb Kenton was an American popular music and jazz artist. As a pianist, composer, arranger and band leader, he led an innovative and influential jazz orchestra for almost four decades. Though Kenton had several pop hits from the early 1940s into the 1960s, his music was always forward-looking.", "url": "https://en.wikipedia.org/wiki/Stan_Kenton"},
  "https://archive.org/details/lp_sing-the-end-of-the-world-and-other-gre_the-mills-brothers": {"kind": "artist", "name": "The Mills Brothers", "text": "The Mills Brothers, sometimes billed The Four Mills Brothers and originally known as Four Boys and a Guitar, are an American vocal jazz and traditional pop vocal quartet who made more than 2,000 recordings that sold more than 50 million copies and garnered at least three dozen gold records.", "url": "https://en.wikipedia.org/wiki/The_Mills_Brothers"},
  "https://archive.org/details/lp_sensational-ink-spots_charlie-owens-sensational-ink-spots": {"kind": "artist", "name": "The Ink Spots", "text": "The Ink Spots were an American vocal pop group who gained international fame in the 1930s and 1940s. Their unique musical style predated the rhythm and blues and rock and roll musical genres, and the subgenre doo-wop. The Ink Spots were widely accepted in both the white and black communities, largely due to the ballad style introduced to the group by lead singer Bill Kenny.", "url": "https://en.wikipedia.org/wiki/The_Ink_Spots"},
  "https://archive.org/details/muddy-waters-electric-mud-black-cover-indianapolis-pressing-mix": {"kind": "album", "name": "Electric Mud", "text": "Electric Mud is the fifth studio album by Muddy Waters, with members of Rotary Connection playing as his backing band. Released in 1968, it presents Muddy Waters as a psychedelic musician. Producer Marshall Chess suggested that Muddy Waters record it in an attempt to appeal to a rock audience.", "url": "https://en.wikipedia.org/wiki/Electric_Mud"},
  "https://archive.org/details/john-lee-hooker-if-you-missim-i-got-im-bluesway-abc-bls-6038-side-a": {"kind": "artist", "name": "John Lee Hooker", "text": "John Lee Hooker was an American blues singer, songwriter, and guitarist. The son of a sharecropper, he rose to prominence performing an electric guitar-style adaptation of Delta blues that he developed in Detroit. Hooker often incorporated other elements, including talking blues and early North Mississippi hill country blues.", "url": "https://en.wikipedia.org/wiki/John_Lee_Hooker"},
  "https://archive.org/details/blues-is-king": {"kind": "album", "name": "Blues Is King", "text": "Blues Is King is a live album by blues musician, B.B. King recorded in Chicago in 1966 and released by the BluesWay label in 1967.", "url": "https://en.wikipedia.org/wiki/Blues_Is_King"},
  "https://archive.org/details/free-form-patterns-1968": {"kind": "album", "name": "Free Form Patterns", "text": "Free Form Patterns is an album by the blues musician Lightnin' Hopkins backed by the rhythm section of the 13th Floor Elevators, recorded in Texas in 1968 and released on the International Artists label.", "url": "https://en.wikipedia.org/wiki/Free_Form_Patterns"},
  "https://archive.org/details/lp_the-corrupt-ones_georges-garvarentz-dusty-springfield": {"kind": "artist", "name": "Georges Garvarentz", "text": "Georges Diran Garvarentz was an Armenian-French composer, noted for his music for films and Charles Aznavour's songs.", "url": "https://en.wikipedia.org/wiki/Georges_Garvarentz"},
  "https://archive.org/details/1965-astrud-gilberto-the-astrud-gilberto-album": {"kind": "album", "name": "The Astrud Gilberto Album", "text": "The Astrud Gilberto Album (with Antonio Carlos Jobim) is the debut studio album by Astrud Gilberto. With Antonio Carlos Jobim on guitar and the arrangements by Marty Paich, it was released via Verve Records in 1965. It peaked at number 41 on the Billboard 200 chart. In 2017, NPR placed it at number 73 on the \"150 Greatest Albums Made by Women\" list.", "url": "https://en.wikipedia.org/wiki/The_Astrud_Gilberto_Album"},
  "https://archive.org/details/lp_at-the-stratford-shakespearean-festival_the-oscar-peterson-trio": {"kind": "artist", "name": "Oscar Peterson", "text": "Oscar Emmanuel Peterson was a Canadian jazz pianist and composer. As a virtuoso who is considered to be one of the greatest jazz pianists of all time, Peterson released more than 200 recordings, won eight Grammy Awards, as well as a lifetime achievement award from the Recording Academy, and received numerous other awards and honours. He played thousands of concerts worldwide in a career lasting more than 60 years.", "url": "https://en.wikipedia.org/wiki/Oscar_Peterson"},
  "https://archive.org/details/lp_jazz-sampler_various-albert-nicholas-art-tatum-art-t": {"kind": "artist", "name": "Erroll Garner", "text": "Erroll Louis Garner was an American jazz pianist and composer known for his swing playing and ballads. His instrumental ballad \"Misty\", his best-known composition, has become a jazz standard. It was first recorded in 1956, with Mitch Miller and his orchestra, and played a prominent part in the 1971 motion picture Play Misty for Me.", "url": "https://en.wikipedia.org/wiki/Erroll_Garner"},
  "https://archive.org/details/lp_stranger-in-paradise-its-a-sin-to-tell-a_don-gardner-trio-jimmy-smith-the-wilson-le": {"kind": "artist", "name": "Jimmy Smith", "text": "James Oscar Smith was an American jazz musician who helped popularize the Hammond B-3 organ, creating a link between jazz and 1960s soul music.", "url": "https://en.wikipedia.org/wiki/Jimmy_Smith_(musician)"},
  "https://archive.org/details/lp_cry-young_ahmad-jamal_0": {"kind": "album", "name": "Cry Young", "text": "Cry Young is an album by American jazz pianist Ahmad Jamal featuring performances recorded in 1967 and released on the Cadet label.", "url": "https://en.wikipedia.org/wiki/Cry_Young"},
  "https://archive.org/details/lp_be-my-love_keely-smith": {"kind": "artist", "name": "Keely Smith", "text": "Dorothy Jacqueline Keely, professionally known as Keely Smith, was an American jazz and popular music singer, who performed and recorded extensively in the 1950s with her then-husband Louis Prima, and throughout the 1960s as a solo artist.", "url": "https://en.wikipedia.org/wiki/Keely_Smith"},
  "https://archive.org/details/lp_together_louis-prima-keely-smith": {"kind": "artist", "name": "Louis Prima", "text": "Louis Leo Prima was an American trumpeter, singer, entertainer, and bandleader.", "url": "https://en.wikipedia.org/wiki/Louis_Prima"},
  "https://archive.org/details/christmasdancepa00lani": {"kind": "artist", "name": "Lester Lanin", "text": "Nathaniel Lester Lanin was an American jazz and pop music bandleader. He was famous for long, smoothly arranged medleys, at a consistent rhythm and tempo, which were designed for continuous dancing. Lanin's career began in the late 1920s and his popularity increased through the advent of the LP era. His music remained very popular among fans of the ballroom dance world.", "url": "https://en.wikipedia.org/wiki/Lester_Lanin"},
  "https://archive.org/details/christmasdancepa00garb": {"kind": "artist", "name": "Jan Garber", "text": "Jan Garber was an American violinist and jazz bandleader.", "url": "https://en.wikipedia.org/wiki/Jan_Garber"},
  "https://archive.org/details/haveyourselfmerr00king": {"kind": "artist", "name": "Wayne King", "text": "Harold Wayne King was an American musician, songwriter, and bandleader with a long association with both NBC and CBS. He was referred to as \"the Waltz King\" because much of his most popular music involved waltzes; \"The Waltz You Saved for Me\" was his standard set-closing song in live performance and on numerous radio broadcasts at the height of his career.", "url": "https://en.wikipedia.org/wiki/Wayne_King"},
  "https://archive.org/details/lp_at-christmas-time_teresa-brewer": {"kind": "artist", "name": "Teresa Brewer", "text": "Teresa Brewer was an American singer whose style incorporated pop, country, jazz, R&B, rock 'n roll, musicals, and novelty songs. She was one of the most prolific and popular female singers of the 1950s, recording around 600 songs.", "url": "https://en.wikipedia.org/wiki/Teresa_Brewer"},
  "https://archive.org/details/brendaleemerrychristmasdecember1964fullalbum": {"kind": "album", "name": "Merry Christmas from Brenda Lee", "text": "Merry Christmas from Brenda Lee is the eleventh album by American singer Brenda Lee, released on October 19, 1964 by Decca Records. in 1999, the album was re-released on MCA Nashville, expanded to 18 tracks, and retitled Rockin' Around the Christmas Tree: The Decca Christmas Recordings, which has remained in print ever since.", "url": "https://en.wikipedia.org/wiki/Merry_Christmas_from_Brenda_Lee"},
  "https://archive.org/details/07-white-christmas": {"kind": "album", "name": "Selections from Irving Berlin's White Christmas", "text": "Selections from Irving Berlin's White Christmas is a 1954 album with songs from the musical film White Christmas. Among the featured artists are Bing Crosby, Danny Kaye, and Trudy Stevens, with Peggy Lee, who was not in the movie, singing some parts. It is one of the last 78 rpm albums produced by the Decca label.", "url": "https://en.wikipedia.org/wiki/Selections_from_Irving_Berlin's_White_Christmas"},
  "https://archive.org/details/1948-christmas-songs-by-sinatra": {"kind": "album", "name": "Christmas Songs by Sinatra", "text": "Christmas Songs by Sinatra is the third studio album by the American singer Frank Sinatra. It was released on October 4, 1948, as a 78 rpm album set of four 78 rpm records in an actual album and as a 10-inch LP record featuring a collection of eight holiday songs.", "url": "https://en.wikipedia.org/wiki/Christmas_Songs_by_Sinatra"},
  "https://archive.org/details/BC_Merry-Christmas_FLAC": {"kind": "album", "name": "Merry Christmas", "text": "Merry Christmas is a Christmas-themed compilation album by Bing Crosby that was released in 1945 on Decca Records. It has remained in print through the vinyl, CD, and downloadable file eras, currently as the disc and digital album White Christmas on MCA Records, a part of the Universal Music Group, and currently on vinyl as Merry Christmas on Geffen Records.", "url": "https://en.wikipedia.org/wiki/Merry_Christmas_(Bing_Crosby_album)"},
  "https://archive.org/details/BeachBoys-XmasAlbum-1964": {"kind": "album", "name": "The Beach Boys' Christmas Album", "text": "The Beach Boys' Christmas Album is the seventh studio album by the American rock band the Beach Boys, released November 9, 1964 on Capitol Records. It contains five original songs and seven standards on a Christmas theme. The album proved to be a long-running success during subsequent Christmas seasons, initially reaching No. 6 on Billboard's Christmas LP's chart in its initial release and eventually going gold.", "url": "https://en.wikipedia.org/wiki/The_Beach_Boys'_Christmas_Album"},
  "https://archive.org/details/1962-we-wish-you-a-merry-christmas-ray-conniff": {"kind": "album", "name": "We Wish You a Merry Christmas", "text": "We Wish You a Merry Christmas is a 1962 album by Ray Conniff. The album was one of two platinum albums over the course of Conniff's career and earned him the title of CBS Records Best Selling Artist for 1962.", "url": "https://en.wikipedia.org/wiki/We_Wish_You_a_Merry_Christmas_(Ray_Conniff_album)"},
  "https://archive.org/details/chet-atkins-christmas-with_20211107": {"kind": "artist", "name": "Chet Atkins", "text": "Chester Burton Atkins, nicknamed \"Mister Guitar\" and \"the Country Gentleman\", was a fingerpicking guitar player, arranger and producer who, along with Owen Bradley and Bob Ferguson, created the Nashville sound, the country music style which expanded its appeal to adult pop music fans. He was primarily a guitarist, but he also played the mandolin, fiddle, banjo, and ukulele, and occasionally sang.", "url": "https://en.wikipedia.org/wiki/Chet_Atkins"},
  "https://archive.org/details/the-hollyridge-strings-christmas-music": {"kind": "artist", "name": "Hollyridge Strings", "text": "The Hollyridge Strings was an American studio orchestra that specialized in easy-listening music, and recorded for the Capitol Records label in the 1960s and 1970s. Stu Phillips, Mort Garson, and Perry Botkin, Jr. were among those who produced, arranged, and conducted the group's recordings.", "url": "https://en.wikipedia.org/wiki/Hollyridge_Strings"},
  "https://archive.org/details/liberace-a-liberace-christmas_20211106": {"kind": "artist", "name": "Liberace", "text": "Władziu Valentino Liberace was an American pianist, singer, and actor. He was born in Wisconsin to parents of Italian and Polish origin and enjoyed a career spanning four decades of concerts, recordings, television, motion pictures, and endorsements.", "url": "https://en.wikipedia.org/wiki/Liberace"},
  "https://archive.org/details/the-sound-of-christmas-volume-2-vinyl-rip": {"kind": "artist", "name": "Bing Crosby", "text": "Harry Lillis \"Bing\" Crosby Jr. was an American singer and actor. One of the first multimedia stars, he was one of the most popular and influential musical artists of the 20th century worldwide. Crosby was a leader in record sales, network radio ratings, and motion picture grosses from 1926 to 1977. He was one of the first global cultural icons. Crosby made over 70 feature films and recorded more than 1,600 songs.", "url": "https://en.wikipedia.org/wiki/Bing_Crosby"},
  "https://archive.org/details/vince-guaraldi-charlie-brown-christmas-mono": {"kind": "album", "name": "A Charlie Brown Christmas", "text": "A Charlie Brown Christmas is the eighth studio album by the American jazz pianist Vince Guaraldi. Released by Fantasy Records in December 1965, the album coincided with the debut of the television special A Charlie Brown Christmas featuring the Peanuts comic characters.", "url": "https://en.wikipedia.org/wiki/A_Charlie_Brown_Christmas_(soundtrack)"},
  "https://archive.org/details/bill-doggett-12-songs-of-christmas-king-600-mono-side-1-f-eq-nr": {"kind": "artist", "name": "Bill Doggett", "text": "William Ballard Doggett was an American pianist and organist. He began his career playing swing music before transitioning into rhythm and blues. Best known for his instrumental compositions \"Honky Tonk\" and \"Hippy Dippy\", Doggett was a pioneer of rock and roll. He worked with the Ink Spots, Johnny Otis, Wynonie Harris, Ella Fitzgerald, and Louis Jordan.", "url": "https://en.wikipedia.org/wiki/Bill_Doggett"},
  "https://archive.org/details/the-three-suns-the-sound-of-christmas-side-1-rca-camden-cal-633-re-d-71-ee-dc-ar": {"kind": "artist", "name": "The Three Suns", "text": "The Three Suns were an American pop group, most popular during the 1940s and 1950s.", "url": "https://en.wikipedia.org/wiki/The_Three_Suns"},
  "https://archive.org/details/henry-mancini-orchestra-and-chorus-a-merry-mancini-christmas-rca-victor-lsp-3612": {"kind": "album", "name": "A Merry Mancini Christmas", "text": "A Merry Mancini Christmas is a 1966 album by Henry Mancini of orchestral and choral arrangements of Christmas music. In addition to traditional Christmas songs, it also contains the original Mancini composition \"Carol for Another Christmas\", the theme of the 1964 television film of the same name.", "url": "https://en.wikipedia.org/wiki/A_Merry_Mancini_Christmas"},
  "https://archive.org/details/leroy-anderson-a-christmas-festival-decca-dl-8925-side-1-f-eq": {"kind": "artist", "name": "Leroy Anderson", "text": "Leroy Anderson was an American composer of short, light concert pieces, many of which were introduced by the Boston Pops Orchestra under the direction of Arthur Fiedler.", "url": "https://en.wikipedia.org/wiki/Leroy_Anderson"},
  "https://archive.org/details/arthur-fiedler-boston-pops-pops-christmas-party-side-1-rca-victor-lsc-2329-livin": {"kind": "artist", "name": "Arthur Fiedler", "text": "Arthur Fiedler was an American conductor notable for his association with both the Boston Symphony and Boston Pops orchestras. With a combination of musicianship and showmanship, he made the Boston Pops one of the best-known orchestras in the United States.", "url": "https://en.wikipedia.org/wiki/Arthur_Fiedler"},
  "https://archive.org/details/george-melachrino-his-orchestra-christmas-joy-side-1-rca-victor-lpm-2044-mono-d-": {"kind": "artist", "name": "George Melachrino", "text": "George Melachrino was a musician, composer of film music, and musical director who was English born of Greek and Italian descent. He was an accomplished player of the violin, viola, oboe, clarinet and saxophone.", "url": "https://en.wikipedia.org/wiki/George_Melachrino"},
  "https://archive.org/details/jose-melis-and-his-orchestra-christmas-with-melis-side-1-bronjo-br-1060-stereo-f-eq": {"kind": "artist", "name": "José Melis", "text": "José Melis Guiu was a Cuban-American bandleader and television personality.", "url": "https://en.wikipedia.org/wiki/Jos%C3%A9_Melis"},
  "https://archive.org/details/earl-grant-winter-wonderland-decca-dl-74677-side-1-stereo-et-stylus-f-eq": {"kind": "artist", "name": "Earl Grant", "text": "Earl Grant was an American pianist, organist, and vocalist popular in the 1950s and 1960s.", "url": "https://en.wikipedia.org/wiki/Earl_Grant_(musician)"},
  "https://archive.org/details/living-strings-orchestra-the-spirit-of-christmas-side-1-rca-camden-cas-783-stereo-d-71-ee-f-eq-fb-h": {"kind": "artist", "name": "Living Strings", "text": "The Living Strings were a studio orchestra founded in 1959 by RCA Victor for a series of easy listening recordings issued on the RCA Camden budget label. There were also related groups called the Living Voices, Living Brass, Living Guitars, Living Marimbas, Living Jazz, Living Trio, Living Percussion, and Living Organ.", "url": "https://en.wikipedia.org/wiki/Living_Strings"},
  "https://archive.org/details/andre-kostelanetz-and-his-orchestra-wonderland-of-christmas-side-1-columbia-le-1": {"kind": "artist", "name": "Andre Kostelanetz", "text": "Andre Kostelanetz was a Russian-American popular orchestral music conductor and arranger who was one of the major exponents of popular orchestra music.", "url": "https://en.wikipedia.org/wiki/Andre_Kostelanetz"},
  "https://archive.org/details/eddie-layton-hammond-organ-music-for-christmas-with-chimes-brass-choir-epic-ln-2": {"kind": "artist", "name": "Eddie Layton", "text": "Edward M. Layton was an American stadium organist who played at old Yankee Stadium for nearly 40 years, earning him membership in the New York Sports Hall of Fame.", "url": "https://en.wikipedia.org/wiki/Eddie_Layton"},
  "https://archive.org/details/john-gary-the-john-gary-christmas-album-rca-victor-lsp-2940-stereo-side-1-f-eq-2": {"kind": "artist", "name": "John Gary", "text": "John Gary was an American singer, recording artist, television host, and performer on the musical stage.", "url": "https://en.wikipedia.org/wiki/John_Gary"},
  "https://archive.org/details/paul-mauriat-and-his-orchestra-the-christmas-album-side-1-philips-600-255-stereo-et-stylus-f-eq": {"kind": "artist", "name": "Paul Mauriat", "text": "Paul Julien André Mauriat was a French orchestra leader, conductor of Le Grand Orchestre de Paul Mauriat, who specialized in the easy listening genre. He is best known in the United States for his million-selling remake of André Popp's \"Love is Blue\", which was number 1 for 5 weeks in 1968. Other recordings for which he is known include \"El Bimbo\", \"Toccata\", \"Love in Every Room/Même si tu revenais\", and \"Penelope\".", "url": "https://en.wikipedia.org/wiki/Paul_Mauriat"},
  "https://archive.org/details/raymond-lefevre-and-his-orchestra-merry-christmas-side-1-kapp-record-fcs-4257-st": {"kind": "artist", "name": "Raymond Lefèvre", "text": "Raymond Lefèvre was a French easy listening orchestra leader, arranger and composer.", "url": "https://en.wikipedia.org/wiki/Raymond_Lef%C3%A8vre"},
  "https://archive.org/details/marian-anderson-christmas-carols-side-1-rca-victor-lm-2613-d-71-ee-f-eq": {"kind": "artist", "name": "Marian Anderson", "text": "Marian Anderson, born Marian Elina-Blanche Anderson was an American contralto. She performed a wide range of music, from opera to spirituals. Anderson performed with renowned orchestras in major concert and recital venues throughout the United States and Europe between 1925 and 1965.", "url": "https://en.wikipedia.org/wiki/Marian_Anderson"},
  "https://archive.org/details/jerry-fielding-and-his-brass-choir-favorite-christmas-music": {"kind": "artist", "name": "Jerry Fielding", "text": "Jerry Fielding was an American jazz musician, bandleader, arranger, and film composer. He was a three-time Oscar nominee for Best Original Score, and an Emmy Award winner.", "url": "https://en.wikipedia.org/wiki/Jerry_Fielding"},
  "https://archive.org/details/lp_soulin_lou-rawls_1": {"kind": "artist", "name": "Lou Rawls", "text": "Louis Allen Rawls was an American baritone singer. He released 61 albums, sold more than 40 million records, and had numerous charting singles, most notably the song \"You'll Never Find Another Love Like Mine\". He also worked as a film, television, and voice actor. He was a three-time winner of the Best Male R&B Vocal Performance Grammy Award.", "url": "https://en.wikipedia.org/wiki/Lou_Rawls"},
  "https://archive.org/details/lp_born-to-sing-the-blues_shirley-bassey": {"kind": "album", "name": "Born to Sing the Blues", "text": "Born to Sing the Blues is the debut album by Welsh singer Shirley Bassey.", "url": "https://en.wikipedia.org/wiki/Born_to_Sing_the_Blues"},
  "https://archive.org/details/lp_inspector-clouseau-original-motion-pict_ken-thorne": {"kind": "artist", "name": "Ken Thorne", "text": "Kenneth Thorne was an English composer, conductor, and arranger. He was known for his film and television scores, particularly his collaborations with director Richard Lester. He won an Academy Award for his work on 1965 film version of the musical A Funny Thing Happened on the Way to the Forum, and was also a Grammy and Emmy Award nominee.", "url": "https://en.wikipedia.org/wiki/Ken_Thorne"},
  "https://archive.org/details/lp_sonny-rollins-quintet_sonny-rollins-quintet-kenny-dorham": {"kind": "artist", "name": "Sonny Rollins", "text": "Walter Theodore \"Sonny\" Rollins was an American jazz tenor saxophonist who is widely recognized as one of the most important and influential jazz musicians in history.", "url": "https://en.wikipedia.org/wiki/Sonny_Rollins"},
  "https://archive.org/details/lp_pops-and-prado_perez-prado-and-his-orchestra": {"kind": "artist", "name": "Pérez Prado", "text": "Dámaso Pérez Prado was a Cuban bandleader, pianist, composer and arranger who popularized the mambo in the 1950s. His big band adaptation of the danzón-mambo proved to be a worldwide success with hits such as \"Mambo No. 5\", earning him the nickname \"The King of the Mambo\".", "url": "https://en.wikipedia.org/wiki/P%C3%A9rez_Prado"},
  "https://archive.org/details/lp_i-gotta-be-methis-trip-out_della-reese_0": {"kind": "artist", "name": "Della Reese", "text": "Della Reese was an American singer, actress, television personality, author and ordained minister. As a singer, she recorded blues, gospel, jazz and pop. Several of her singles made the US Hot 100, including the number two charting song, \"Don't You Know?\" (1959).", "url": "https://en.wikipedia.org/wiki/Della_Reese"},
  "https://archive.org/details/lp_four-tops-live_four-tops": {"kind": "album", "name": "Four Tops Live!", "text": "Four Tops Live! is the first live album by American rhythm and blues vocal band The Four Tops, released on Motown in 1966. The album was recorded as part of a series of concerts by the record label featuring their premier artists held in Detroit and had positive critical and commercial reception.", "url": "https://en.wikipedia.org/wiki/Four_Tops_Live!"},
  "https://archive.org/details/lp_the-umbrellas-of-cherbourg-les-parapluies_michel-legrand": {"kind": "artist", "name": "Michel Legrand", "text": "Michel Jean Legrand was a French musical composer, arranger, conductor, jazz pianist, and singer. Legrand was a prolific composer, having written more than 200 film and television scores, in addition to many songs. His scores for two of the films of French New Wave director Jacques Demy, The Umbrellas of Cherbourg (1964) and The Young Girls of Rochefort (1967), earned Legrand his first Academy Award nominations.", "url": "https://en.wikipedia.org/wiki/Michel_Legrand"},
  "https://archive.org/details/lp_the-original-soundtrack-from-the-film-blac_antonio-carlos-jobim-luiz-bonf": {"kind": "artist", "name": "Antônio Carlos Jobim", "text": "Antônio Carlos Brasileiro de Almeida Jobim, also known as Tom Jobim, was a Brazilian composer, pianist, guitarist, songwriter, arranger and singer. Jobim is considered a great exponent of Brazilian music and one of the fathers of bossa nova for having merged samba with cool jazz in the 1960s as a pioneer of the genre.", "url": "https://en.wikipedia.org/wiki/Ant%C3%B4nio_Carlos_Jobim"},
  "https://archive.org/details/lp_the-soul-man_bobby-timmons": {"kind": "album", "name": "The Soul Man!", "text": "The Soul Man! is an album by American jazz pianist Bobby Timmons recorded in 1966 and released on the Prestige Records.", "url": "https://en.wikipedia.org/wiki/The_Soul_Man!"},
  "https://archive.org/details/lp_ballad-of-the-blues_jo-stafford-paul-weston-and-his-orchest_0": {"kind": "album", "name": "Ballad of the Blues", "text": "Ballad of the Blues is an album by vocalist Jo Stafford that was released in 1959. She is supported by the Starlighters, a male vocal quartet, and an orchestra led by Paul Weston, her husband.", "url": "https://en.wikipedia.org/wiki/Ballad_of_the_Blues"},
  "https://archive.org/details/lp_its-party-time-with-king-curtis_king-curtis": {"kind": "artist", "name": "King Curtis", "text": "Curtis Ousley, known professionally as King Curtis, was an American saxophonist who played rhythm and blues, jazz, and rock and roll. A bandleader, band member, and session musician, he was also a musical director and record producer. A master of the instrument, he played tenor, alto, and soprano saxophone.", "url": "https://en.wikipedia.org/wiki/King_Curtis"},
  "https://archive.org/details/lp_the-saxophones-of-sonny-stitt_sonny-stitt": {"kind": "album", "name": "The Saxophones of Sonny Stitt", "text": "The Saxophones of Sonny Stitt is an album by saxophonist Sonny Stitt, released in 1959 on the Roost label.", "url": "https://en.wikipedia.org/wiki/The_Saxophones_of_Sonny_Stitt"},
  "https://archive.org/details/lp_gospel-time_ruth-brown": {"kind": "artist", "name": "Ruth Brown", "text": "Ruth Alston Brown was an American singer-songwriter and actress, sometimes referred to as the \"Queen of R&B\". She was noted for bringing a pop music style to R&B music in a series of hit songs for Atlantic Records in the 1950s, such as \"So Long\", \"Teardrops from My Eyes\" and \"(Mama) He Treats Your Daughter Mean\". For these contributions, Atlantic became known as \"the house that Ruth built\".", "url": "https://en.wikipedia.org/wiki/Ruth_Brown"},
  "https://archive.org/details/lp_3046-people-danced-til-4-am-to-bill-dog_bill-doggett-combo": {"kind": "artist", "name": "Bill Doggett", "text": "William Ballard Doggett was an American pianist and organist. He began his career playing swing music before transitioning into rhythm and blues. Best known for his instrumental compositions \"Honky Tonk\" and \"Hippy Dippy\", Doggett was a pioneer of rock and roll. He worked with the Ink Spots, Johnny Otis, Wynonie Harris, Ella Fitzgerald, and Louis Jordan.", "url": "https://en.wikipedia.org/wiki/Bill_Doggett"},
  "https://archive.org/details/lp_candys-theme-and-other-sweets_hugo-montenegro-and-his-orchestra": {"kind": "artist", "name": "Hugo Montenegro", "text": "Hugo Mario Montenegro was an American orchestra leader and composer of film soundtracks.", "url": "https://en.wikipedia.org/wiki/Hugo_Montenegro"},
  "https://archive.org/details/lp_afro-cuban-jazz-suite_machito": {"kind": "artist", "name": "Machito", "text": "Frank Grillo known professionally as Machito, was a Latin jazz musician who helped refine Afro-Cuban jazz and played a key role in the creation of both Cubop and salsa music. He was raised in Havana with his foster sister, the singer Graciela.", "url": "https://en.wikipedia.org/wiki/Machito"},
  "https://archive.org/details/lp_spotlight-on-earl-grant_earl-grant_0": {"kind": "artist", "name": "Earl Grant", "text": "Earl Grant was an American pianist, organist, and vocalist popular in the 1950s and 1960s.", "url": "https://en.wikipedia.org/wiki/Earl_Grant_(musician)"},
  "https://archive.org/details/lp_into-my-life_chet-baker-the-carmel-strings": {"kind": "album", "name": "Into My Life", "text": "Into My Life is a studio album by jazz trumpeter Chet Baker and the Carmel Strings recorded in 1966 and released on the World Pacific label.", "url": "https://en.wikipedia.org/wiki/Into_My_Life_(album)"},
  "https://archive.org/details/lp_all-the-hits-by-dee-dee-sharp_dee-dee-sharp": {"kind": "artist", "name": "Dee Dee Sharp", "text": "Dione LaRue, known professionally as Dee Dee Sharp, is an American R&B singer. She was one of the first Black female teenage pop stars to achieve mainstream national success in the early 1960s.", "url": "https://en.wikipedia.org/wiki/Dee_Dee_Sharp"},
  "https://archive.org/details/lp_sol-madrid-music-from-the-original-soun_lalo-schifrin": {"kind": "artist", "name": "Lalo Schifrin", "text": "Boris Claudio \"Lalo\" Schifrin was an Argentine and American pianist, composer, arranger and conductor. Initially prominent as a jazz composer, he was best known for his large body of film and television scores, which incorporates jazz and Latin American musical elements alongside traditional orchestration.", "url": "https://en.wikipedia.org/wiki/Lalo_Schifrin"},
  "https://archive.org/details/lp_mambo_perez-prado-and-his-orchestra-tito-rodr": {"kind": "artist", "name": "Pérez Prado", "text": "Dámaso Pérez Prado was a Cuban bandleader, pianist, composer and arranger who popularized the mambo in the 1950s. His big band adaptation of the danzón-mambo proved to be a worldwide success with hits such as \"Mambo No. 5\", earning him the nickname \"The King of the Mambo\".", "url": "https://en.wikipedia.org/wiki/P%C3%A9rez_Prado"},
  "https://archive.org/details/lp_live_lou-rawls_0": {"kind": "artist", "name": "Lou Rawls", "text": "Louis Allen Rawls was an American baritone singer. He released 61 albums, sold more than 40 million records, and had numerous charting singles, most notably the song \"You'll Never Find Another Love Like Mine\". He also worked as a film, television, and voice actor. He was a three-time winner of the Best Male R&B Vocal Performance Grammy Award.", "url": "https://en.wikipedia.org/wiki/Lou_Rawls"},
  "https://archive.org/details/lp_dirty-dog_kai-winding": {"kind": "album", "name": "Dirty Dog", "text": "Dirty Dog is an album by jazz trombonist and arranger Kai Winding recorded in 1966 for the Verve label.", "url": "https://en.wikipedia.org/wiki/Dirty_Dog_(album)"},
  "https://archive.org/details/lp_provocative-percussion-vol-iii_enoch-light-and-the-light-brigade": {"kind": "album", "name": "Provocative Percussion Vol. III", "text": "Provocative Percussion Vol. III is a studio album by Enoch Light and the Light Brigade. It was produced by Light and released in 1961 on Light's Command Records label. The featured musicians included Tony Mottola (guitar), Doc Severinsen (trumpet), Bobby Byrne (trombone), Urbie Green, Bob Haggart, Phil Bodner, Stanley Webb, Moe Wechsler and Joe Wilder. The arrangements were by Lew Davies.", "url": "https://en.wikipedia.org/wiki/Provocative_Percussion_Vol._III"},
  "https://archive.org/details/lp_hugh-masekelas-next-album_hugh-masekela": {"kind": "album", "name": "Hugh Masekela's Next Album", "text": "Hugh Masekela's Next Album is the fourth studio album by South African jazz trumpeter Hugh Masekela. It was recorded in New York City and released in December 1966 via MGM Records label. The album consists mainly of covers of pop songs.", "url": "https://en.wikipedia.org/wiki/Hugh_Masekela's_Next_Album"},
  "https://archive.org/details/lp_wild-wonderful-wynona_wynona-carr": {"kind": "artist", "name": "Wynona Carr", "text": "Wynona Merceris Carr was an American gospel, R&B and rock and roll singer-songwriter, who recorded as Sister Wynona Carr when performing gospel material.", "url": "https://en.wikipedia.org/wiki/Wynona_Carr"},
  "https://archive.org/details/lp_the-new-james_harry-james-and-his-orchestra": {"kind": "album", "name": "The New James", "text": "The New James is a studio album by American trumpeter Harry James with The Harry James Orchestra. The album was recorded April 1–3, 1958 and released by Capitol Records on stereo LP (ST-1037), mono LP (T-1037), and a series of three EPs.", "url": "https://en.wikipedia.org/wiki/The_New_James"},
  "https://archive.org/details/lp_soul-food_bobby-timmons": {"kind": "album", "name": "Soul Food", "text": "Soul Food is an album by American jazz pianist Bobby Timmons recorded in 1966 and released on the Prestige label.", "url": "https://en.wikipedia.org/wiki/Soul_Food_(Bobby_Timmons_album)"},
  "https://archive.org/details/lp_caterina-valentes-greatest-hits_caterina-valente-verner-muller-und-sein-or": {"kind": "artist", "name": "Caterina Valente", "text": "Caterina Germaine Maria Valente was an Italian-French multilingual singer, guitarist, and dancer. She spoke six languages and sang in thirteen. While she was best known as a performer in Europe, Valente spent part of her career in the United States, where she performed alongside Bing Crosby, Dean Martin, Perry Como, and Ella Fitzgerald, among others.", "url": "https://en.wikipedia.org/wiki/Caterina_Valente"},
  "https://archive.org/details/lp_they-call-me-mister-tibbs_quincy-jones": {"kind": "artist", "name": "Quincy Jones", "text": "Quincy Delight Jones Jr. was an American record producer, musician, and composer. During his seven-decade career, he received dozens of accolades, including 28 Grammy Awards, a Primetime Emmy Award, and a Tony Award as well as nominations for seven Academy Awards and four Golden Globe Awards.", "url": "https://en.wikipedia.org/wiki/Quincy_Jones"},
  "https://archive.org/details/lp_josh-white-at-town-hall_josh-white-beverly-white-josh-white-jr-jos": {"kind": "artist", "name": "Josh White", "text": "Joshua Daniel White was an American singer, guitarist, songwriter, actor and civil rights activist. He also recorded under the names Pinewood Tom and Tippy Barton in the 1930s.", "url": "https://en.wikipedia.org/wiki/Josh_White"},
  "https://archive.org/details/lp_beautiful-friendship_the-three-sounds_0": {"kind": "artist", "name": "The 3 Sounds", "text": "The 3 Sounds was an American jazz piano trio that formed in 1956 and disbanded in 1973.", "url": "https://en.wikipedia.org/wiki/The_3_Sounds"},
  "https://archive.org/details/lp_country-meets-the-blues_the-ramsey-lewis-trio_0": {"kind": "album", "name": "Country Meets the Blues", "text": "Country Meets the Blues is an album of jazz interpretations of country music and blues tunes performed by the Ramsey Lewis' Trio which was recorded in 1962 and released on the Argo label.", "url": "https://en.wikipedia.org/wiki/Country_Meets_the_Blues"}
};
